use vstd::prelude::*;

verus! {

    // Mathematical specification: does there exist an index j
    // with 0 <= j < a.len()-1 such that a[j] + 1 == a[j+1]?
    spec fn contains_consecutive_seq(a: Seq<i32>) -> bool
        decreases a
    {
        if a.len() < 2 {
            false
        } else {
            exists |j: nat|
                j + 1 < a.len() &&
                a[j] + 1 == a[j + 1]
        }
    }

    // Implementation over a Rust Vec<i32>, verified to match the spec above.
    fn contains_consecutive_numbers(a: &Vec<i32>) -> (result: bool)
        ensures
            result == contains_consecutive_seq(view(a))
    {
        let len: usize = a.len();
        let mut i: usize = 0;
        // We scan until i+1 == len, i.e. i == len-1
        while i + 1 < len
            // As usual, we must keep i <= len to avoid OOB
            invariant
                i <= len,
                // For every index j < i that *has* a valid j+1,
                // we have already checked a[j]+1 != a[j+1].
                forall |j: nat|
                    j < i as nat &&
                    j + 1 < view(a).len()
                    ==> view(a)[j] + 1 != view(a)[j + 1],
            decreases
                len - i
        {
            // If we find a match at (i, i+1) we return true immediately,
            // and discharge the ensures by supplying a witness j == i.
            if a[i] + 1 == a[i + 1] {
                return true by {
                    let s = view(a);
                    let j: nat = i as nat;
                    // j+1 < s.len() is exactly the loop‐guard `i+1 < len`
                    assert(j + 1 < s.len());
                    // And we just tested equality
                    assert(s[j] + 1 == s[j + 1]);
                };
            } else {
                // We also assert the negative branch so that when we
                // increment i, the loop invariant still holds.
                assert(a[i] + 1 != a[i + 1]);
            }
            i = i + 1;
        }
        // If we finish the scan, no pair was found
        false
    }
}

